import { useState } from 'react';
import {
  JxStack,
  JxHeading,
  JxText,
  JxBadge,
  JxDivider,
  JxSegmentedControl,
  JxSegmentedControlItem,
  JxSlider,
  JxSwitch,
  JxSelect,
} from '@jinx-ui/react';

type Theme = 'light' | 'dark' | 'system';
type Font = 'system' | 'serif' | 'mono';

export interface AppearanceSettings {
  theme: Theme;
  scale: number;
  dense: boolean;
  font: Font;
}

interface AppearanceSettingsScreenProps {
  defaultSettings?: Partial<AppearanceSettings>;
  onChange?: (settings: AppearanceSettings) => void;
}

const THEME_LABELS: Record<Theme, string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

const FONT_OPTIONS: { value: Font; label: string }[] = [
  { value: 'system', label: 'Системный' },
  { value: 'serif', label: 'С засечками' },
  { value: 'mono', label: 'Моноширинный' },
];

function AppearanceSettingsScreen({ defaultSettings, onChange }: AppearanceSettingsScreenProps) {
  const [theme, setTheme] = useState<Theme>(defaultSettings?.theme ?? 'system');
  const [scale, setScale] = useState<number>(defaultSettings?.scale ?? 100);
  const [dense, setDense] = useState<boolean>(defaultSettings?.dense ?? false);
  const [font, setFont] = useState<Font>(defaultSettings?.font ?? 'system');

  const emit = (next: Partial<AppearanceSettings>) => {
    onChange?.({
      theme: next.theme ?? theme,
      scale: next.scale ?? scale,
      dense: next.dense ?? dense,
      font: next.font ?? font,
    });
  };

  const handleThemeChange = (value: string) => {
    const next = value as Theme;
    setTheme(next);
    emit({ theme: next });
  };

  const handleScaleChange = (value: number) => {
    setScale(value);
    emit({ scale: value });
  };

  const handleDenseChange = (value: boolean) => {
    setDense(value);
    emit({ dense: value });
  };

  const handleFontChange = (value: string) => {
    const next = value as Font;
    setFont(next);
    emit({ font: next });
  };

  return (
    <JxStack direction="column" gap="lg" className="jx-p-lg">
      <JxStack direction="row" align="center" justify="between">
        <JxHeading level={2}>Внешний вид</JxHeading>
        <JxBadge variant="neutral">{THEME_LABELS[theme]}</JxBadge>
      </JxStack>

      <JxStack direction="column" gap="sm">
        <JxText size="sm" weight="medium">
          Тема оформления
        </JxText>
        <JxSegmentedControl value={theme} onValueChange={handleThemeChange} aria-label="Тема оформления">
          <JxSegmentedControlItem value="light">Светлая</JxSegmentedControlItem>
          <JxSegmentedControlItem value="dark">Тёмная</JxSegmentedControlItem>
          <JxSegmentedControlItem value="system">Системная</JxSegmentedControlItem>
        </JxSegmentedControl>
      </JxStack>

      <JxStack direction="column" gap="sm">
        <JxStack direction="row" align="center" justify="between">
          <JxText size="sm" weight="medium">
            Масштаб интерфейса
          </JxText>
          <JxText size="sm" tone="muted">
            {scale}%
          </JxText>
        </JxStack>
        <JxSlider
          value={scale}
          onValueChange={handleScaleChange}
          min={80}
          max={140}
          step={5}
          aria-label="Масштаб интерфейса"
        />
      </JxStack>

      <JxStack direction="row" align="center" justify="between">
        <JxStack direction="column" gap="xs">
          <JxText size="sm" weight="medium">
            Плотная вёрстка
          </JxText>
          <JxText size="sm" tone="muted">
            Меньше отступов между элементами
          </JxText>
        </JxStack>
        <JxSwitch value={dense} onValueChange={handleDenseChange} aria-label="Плотная вёрстка" />
      </JxStack>

      <JxDivider />

      <JxStack direction="column" gap="sm">
        <JxText size="sm" weight="medium" tone="muted">
          Ещё
        </JxText>
        <JxStack direction="row" align="center" justify="between">
          <JxText size="sm">Шрифт</JxText>
          <JxSelect value={font} onValueChange={handleFontChange} aria-label="Шрифт" options={FONT_OPTIONS} />
        </JxStack>
      </JxStack>
    </JxStack>
  );
}

export default AppearanceSettingsScreen;

